CREATE OR REPLACE FUNCTION public.resolve_gateway_payment_token(p_link_id uuid,p_user_id uuid DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_ref text; v_user uuid; v_status text; v_secret text; BEGIN SELECT user_id,status,secret_ref INTO v_user,v_status,v_ref FROM public.gateway_payment_token_links WHERE id=p_link_id AND (p_user_id IS NULL OR user_id=p_user_id) FOR SHARE; IF NOT FOUND OR v_status<>'active' THEN RAISE EXCEPTION 'payment_token_link_unavailable'; END IF; IF p_user_id IS NULL THEN RAISE EXCEPTION 'tenant_required'; END IF; IF v_user<>p_user_id THEN RAISE EXCEPTION 'tenant_mismatch'; END IF; IF v_ref IS NULL OR length(v_ref)<1 THEN RAISE EXCEPTION 'payment_token_secret_missing'; END IF; SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE id=v_ref::uuid; IF v_secret IS NULL THEN RAISE EXCEPTION 'payment_token_secret_unavailable'; END IF; RETURN v_secret; END; $$; REVOKE ALL ON FUNCTION public.resolve_gateway_payment_token(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.resolve_gateway_payment_token(uuid,uuid) TO service_role;